<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Wireframe</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 20px 0;
    font-family: Arial, sans-serif;
    background: #fff;
    display: flex;
    justify-content: center;
  }
  .column {
    width: 45%;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
  }
  .box {
    border: 1px solid #000;
    background: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
  }
  .row {
    width: 100%;
    display: flex;
    justify-content: center;
    gap: 8px;
  }
  #box-1 { width: 100%; height: 70px; }
  #box-2 { width: 85%; height: 70px; }
  #box-3 { width: 25%; height: 70px; }
  #box-4 { flex: 1; height: 70px; }
  #box-5, #box-6, #box-7 { width: 20%; height: 65px; }
  #box-8 { width: 45%; height: 65px; }
  .container {
    width: 90%;
    border: 1px dashed #000;
    background: #fff;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 24px 10px 10px 10px;
  }
  .container-label {
    position: absolute;
    top: 4px;
    right: 4px;
    font-size: 11px;
    border: 1px solid #000;
    background: #fff;
    padding: 1px 4px;
  }
  #box-9 { width: 60%; height: 65px; }
  #box-10 { width: 50%; height: 65px; }
  #box-11 { width: 60%; height: 65px; }
  #box-12 { width: 55%; height: 65px; }
  #box-13 { width: 47%; height: 65px; }
</style>
</head>
<body>
  <div class="column">
    <div class="box" id="box-1">box-1</div>
    <div class="box" id="box-2">box-2</div>
    <div class="row">
      <div class="box" id="box-3">box-3</div>
      <div class="box" id="box-4">box-4</div>
    </div>
    <div class="row">
      <div class="box" id="box-5">box-5</div>
      <div class="box" id="box-6">box-6</div>
      <div class="box" id="box-7">box-7</div>
    </div>
    <div class="box" id="box-8">box-8</div>
    <div class="container">
      <span class="container-label">container-1</span>
      <div class="box" id="box-9">box-9</div>
      <div class="box" id="box-10">box-10</div>
      <div class="box" id="box-11">box-11</div>
      <div class="box" id="box-12">box-12</div>
      <div class="box" id="box-13">box-13</div>
    </div>
  </div>
</body>
</html>
